const { useState } = React;

function Child({ label }) {
  console.log('Child 렌더');
  return <p>{label}</p>;
}
function App() {
  const [count, setCount] = useState(0);
  console.log('App 렌더');
  return (
    <main>
      <button type="button" onClick={() => setCount(count + 1)}>부모 state: {count}</button>
      <Child label="변하지 않는 자식 props" />
    </main>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

